// 0. Appel authentifié uniquement : l'API envoie le secret partagé dans l'en-tête
//    x-campus360-secret. Sans lui, rien n'est envoyé (fail closed).
const headers = $json.headers || {};
const expectedSecret = ($env.N8N_STAGE_WEBHOOK_SECRET || '').trim();
if (!expectedSecret || (headers['x-campus360-secret'] || '').trim() !== expectedSecret) {
  throw new Error('Appel non autorisé : secret absent ou invalide.');
}

const body = $json.body || $json;
const required = (value, label) => {
  const text = typeof value === 'string' ? value.trim() : '';
  if (!text) throw new Error(`Champ requis manquant : ${label}`);
  return text;
};
const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const toCameroonDigits = (raw) => {
  const digits = String(raw || '').replace(/[^0-9]/g, '');
  return digits.startsWith('6') && digits.length === 9 ? `237${digits}` : digits;
};

// 1. Identifiant unique de la candidature (créé par l'API)
const applicationId = required(body.applicationId, 'applicationId');

// 2. Canal de diffusion cible ('whatsapp' | 'email')
const channel = String(body.channel || '').toLowerCase().trim() === 'email' ? 'email' : 'whatsapp';

// 3. Données étudiant : uniquement celles transmises par l'API, aucune valeur inventée
const student = body.student || {};
const studentFullName = required(student.fullName || student.name, 'student.fullName');
const studentEmail = required(student.email, 'student.email');
const studentPhone = toCameroonDigits(student.phoneWhatsapp || student.phone);
const instanceName = (student.instanceName || '').trim();
if (channel === 'whatsapp' && !instanceName) throw new Error('Champ requis manquant : student.instanceName');
const studentMajor = (student.major || '').trim();
const studentUniversity = (student.university || '').trim();

// 4. Données recruteur / offre
const job = body.job || {};
const jobTitle = (job.title || '').trim() || 'votre offre de stage';
const companyName = required(job.companyName || job.company || body.companyName, 'job.companyName');
const jobLocation = (job.location || '').trim();
const recruiterPhone = toCameroonDigits(job.recruiterWhatsapp || job.phone);
const recruiterEmail = (job.recruiterEmail || job.email || '').trim();
if (channel === 'whatsapp' && !recruiterPhone) throw new Error('Champ requis manquant : job.recruiterWhatsapp');
if (channel === 'email' && !recruiterEmail) throw new Error('Champ requis manquant : job.recruiterEmail');

// 5. Dossier de candidature : le CV de l'étudiant est obligatoire
const dossier = body.dossier || {};
const cvPdfUrl = required(dossier.cvPdfUrl || body.cvPdfUrl, 'dossier.cvPdfUrl');
const letterText = (dossier.letterText || body.letterText || '').trim();
const studyLine = studentMajor ? ` en *${studentMajor}*${studentUniversity ? ` (${studentUniversity})` : ''}` : '';
const locationLine = jobLocation ? ` à *${jobLocation}*` : '';

// Construction du pitch WhatsApp officiel
const defaultPitch = `📢 *Nouvelle Candidature — Campus 360*\n\nBonjour *${companyName}*,\n\nJe suis *${studentFullName}*, étudiant${studyLine}.\n\nJ'ai l'honneur de postuler à votre offre : *${jobTitle}*${locationLine}.\n\n📄 Mon CV est joint à ce message (document PDF ci-dessus).\n\n${letterText ? `💬 *Présentation du profil :*\n${letterText.slice(0, 320)}${letterText.length > 320 ? '...' : ''}\n\n` : ''}${studentPhone ? `📞 *WhatsApp Direct :* https://wa.me/${studentPhone}\n` : ''}✉️ *Email Candidat :* ${studentEmail}\n🆔 *Réf. Candidature :* ${applicationId}\n\nBien cordialement,\n*${studentFullName}* (Postulé via Campus 360)`;
const whatsappPitch = dossier.whatsappPitch || body.whatsappPitch || defaultPitch;

// Valeurs échappées pour l'e-mail HTML (le contenu vient de l'étudiant)
const h = {
  jobTitle: escapeHtml(jobTitle),
  companyName: escapeHtml(companyName),
  studentFullName: escapeHtml(studentFullName),
  study: escapeHtml([studentMajor, studentUniversity].filter(Boolean).join(' · ')),
  studentPhone: escapeHtml(studentPhone),
  studentEmail: escapeHtml(studentEmail),
  jobLocation: escapeHtml(jobLocation),
  letterText: escapeHtml(letterText),
  cvPdfUrl: escapeHtml(cvPdfUrl),
  applicationId: escapeHtml(applicationId),
};

// 6. Calcul du Jitter Anti-Ban aléatoire (15 à 30 secondes pour envois groupés)
const jitterSeconds = Math.floor(Math.random() * 16) + 15;

// 7. Formatage de l'email SMTP professionnel HTML
const emailSubject = `Candidature : ${jobTitle} — ${studentFullName}`;
const emailHtml = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Candidature Campus 360</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #f8fafc; color: #1e293b; margin: 0; padding: 24px; line-height: 1.6; }
    .wrapper { max-width: 620px; margin: 0 auto; background: #ffffff; border-radius: 12px; border: 1px solid #e2e8f0; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05); }
    .header { background: #0f172a; color: #ffffff; padding: 28px 24px; text-align: center; }
    .badge { display: inline-block; background: #2563eb; color: #ffffff; padding: 4px 14px; border-radius: 9999px; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 10px; }
    .title { margin: 0; font-size: 20px; font-weight: 700; color: #ffffff; }
    .subtitle { margin: 6px 0 0 0; font-size: 14px; color: #94a3b8; }
    .content { padding: 28px 24px; }
    .info-card { background: #f1f5f9; border-radius: 8px; padding: 18px; margin: 18px 0; border-left: 4px solid #2563eb; }
    .info-card p { margin: 6px 0; font-size: 14px; }
    .motivation-box { background: #f8fafc; border-radius: 8px; padding: 16px; border: 1px dashed #cbd5e1; font-style: italic; color: #334155; margin: 16px 0; white-space: pre-line; }
    .cta-container { text-align: center; margin: 28px 0; }
    .cta-btn { display: inline-block; background: #2563eb; color: #ffffff !important; text-decoration: none; padding: 14px 28px; border-radius: 8px; font-weight: 600; font-size: 15px; }
    .footer { padding: 20px 24px; background: #f8fafc; border-top: 1px solid #e2e8f0; font-size: 12px; color: #64748b; text-align: center; line-height: 1.5; }
  </style>
</head>
<body>
  <div class="wrapper">
    <div class="header">
      <div class="badge">Campus 360 • Candidature</div>
      <h1 class="title">Nouvelle Candidature Reçue</h1>
      <p class="subtitle">${h.jobTitle} chez ${h.companyName}</p>
    </div>
    <div class="content">
      <p>Bonjour l'équipe Recrutement de <strong>${h.companyName}</strong>,</p>
      <p>Un candidat qualifié de la plateforme <strong>Campus 360</strong> vient de postuler à votre offre de stage.</p>
      <div class="info-card">
        <p><strong>👤 Candidat :</strong> ${h.studentFullName}</p>
        ${h.study ? `<p><strong>🎓 Formation :</strong> ${h.study}</p>` : ''}
        ${studentPhone ? `<p><strong>📞 WhatsApp :</strong> +${h.studentPhone}</p>` : ''}
        <p><strong>✉️ Email :</strong> ${h.studentEmail}</p>
        ${jobLocation ? `<p><strong>📍 Localisation :</strong> ${h.jobLocation}</p>` : ''}
      </div>
      <h3 style="margin-top: 24px; font-size: 15px; color: #0f172a;">Lettre de motivation & accroche :</h3>
      <div class="motivation-box">${h.letterText}</div>
      <div class="cta-container">
        <a href="${h.cvPdfUrl}" class="cta-btn" target="_blank">📄 Consulter le CV Officiel (PDF)</a>
      </div>
      <p style="font-size: 13px; color: #64748b; margin-top: 20px;">
        💡 <strong>Réponse directe :</strong> Vous pouvez répondre directement à cet email. L\'en-tête <em>Reply-To</em> est configuré pour joindre <strong>${h.studentEmail}</strong>.
      </p>
    </div>
    <div class="footer">
      Campus 360 — Plateforme d\'insertion professionnelle étudiante en Afrique.<br>
      Identifiant dossier : <code>${h.applicationId}</code>
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    applicationId,
    channel,
    jitterSeconds,
    student: {
      fullName: studentFullName,
      phoneWhatsapp: studentPhone,
      email: studentEmail,
      major: studentMajor,
      university: studentUniversity,
      instanceName
    },
    job: {
      title: jobTitle,
      companyName,
      location: jobLocation,
      recruiterWhatsapp: recruiterPhone,
      recruiterEmail
    },
    dossier: {
      cvPdfUrl,
      letterText,
      whatsappPitch
    },
    emailSubject,
    emailHtml,
    dispatchedAt: new Date().toISOString()
  }
}];

parameters.jsonBody:
={{ JSON.stringify({
  number: $json.job.recruiterWhatsapp,
  mediatype: 'document',
  mimetype: 'application/pdf',
  media: $json.dossier.cvPdfUrl,
  fileName: 'CV_Officiel.pdf',
  caption: $json.dossier.whatsappPitch
}) }}

={{ JSON.stringify({
  from: 'Campus 360 <onboarding@resend.dev>',
  to: [$json.job.recruiterEmail],
  reply_to: $json.student.email,
  subject: $json.emailSubject,
  html: $json.emailHtml
}) }}
